from datetime import date, datetime
from decimal import Decimal

from sqlalchemy import (
    BigInteger,
    Boolean,
    Date,
    DateTime,
    Float,
    ForeignKey,
    Index,
    Integer,
    Numeric,
    String,
    UniqueConstraint,
    func,
)
from sqlalchemy.orm import Mapped, mapped_column

from app.db import Base


class User(Base):
    __tablename__ = "users"

    # `id` IS the Telegram user id, supplied by the bot on every request -
    # never generated by the database. BigInteger because Telegram user
    # ids routinely exceed the 32-bit Integer range (roughly 2.1 billion)
    # for accounts created in the last few years; autoincrement is off
    # since the app always provides this value explicitly (see
    # app/crud.py::get_or_create_user).
    id: Mapped[int] = mapped_column(BigInteger, primary_key=True, autoincrement=False)
    telegram_chat_id: Mapped[str] = mapped_column(String, nullable=False)
    created_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now())


class Bill(Base):
    __tablename__ = "bills"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    # BigInteger to match User.id's type exactly - a FK column narrower
    # than the column it references is a real (if quiet) foot-gun.
    user_id: Mapped[int] = mapped_column(BigInteger, ForeignKey("users.id"), index=True)

    # Only the three fields the Sanitizer is allowed to keep. The source
    # image never reaches this table, or any table.
    institution: Mapped[str] = mapped_column(String, index=True)
    amount: Mapped[Decimal] = mapped_column(Numeric(12, 2))
    # ISO 4217 code (e.g. "ILS", "USD", "EUR"), never a symbol - the
    # Sanitizer's VisionSanitizerService guarantees this is always a
    # valid-shaped 3-letter code, defaulting to ILS when the bill shows no
    # currency at all. See app/vision.py::VisionSanitizerService.
    currency: Mapped[str] = mapped_column(String(3), default="ILS", server_default="ILS")
    # One of the three Hebrew labels the Vision AI classifies the bill
    # into (see app/vision.py::_ALLOWED_CATEGORIES), or null when the
    # model couldn't confidently classify it - there's no default here on
    # purpose, unlike currency's ILS fallback; see the note in
    # VisionSanitizerService.extract_bill_fields.
    category: Mapped[str | None] = mapped_column(String, nullable=True)
    # Nullable: the Sanitizer returns null when no due date is visible on
    # the bill. A bill with no due date is simply never picked up by the
    # Enforcer's due-window scan (`due_date <= cutoff` is never true
    # against NULL) - that's correct, not a bug to work around.
    due_date: Mapped[date | None] = mapped_column(Date, nullable=True)

    status: Mapped[str] = mapped_column(String, default="pending_analysis")
    # Payment confirmation number, typed in by the user during the /pay
    # flow's follow-up step (telegram_bot.py::process_asmachta_step).
    # Optional - null when the user skipped it ("דלג") or the bill was
    # marked paid some other way.
    asmachta: Mapped[str | None] = mapped_column(String, nullable=True)
    is_anomaly: Mapped[bool | None] = mapped_column(Boolean, nullable=True)
    anomaly_reason: Mapped[str | None] = mapped_column(String, nullable=True)

    alert_sent_at: Mapped[datetime | None] = mapped_column(DateTime, nullable=True)
    alert_attempts: Mapped[int] = mapped_column(Integer, default=0)

    created_at: Mapped[datetime] = mapped_column(DateTime, server_default=func.now())

    __table_args__ = (
        # The Enforcer's cron scan filters on exactly these two columns -
        # this is what keeps that query an index range scan, not a full
        # table scan, as the bills table grows.
        Index("ix_bills_due_alert_window", "due_date", "alert_sent_at"),
    )


class InstitutionStats(Base):
    """Rolling per-(user, institution) statistics, updated incrementally via
    Welford's algorithm on every new bill. Lets the Analyst Agent do an O(1)
    anomaly check instead of re-scanning a user's bill history each time."""

    __tablename__ = "institution_stats"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    user_id: Mapped[int] = mapped_column(BigInteger, ForeignKey("users.id"))
    institution: Mapped[str] = mapped_column(String)

    count: Mapped[int] = mapped_column(Integer, default=0)
    mean_amount: Mapped[float] = mapped_column(Float, default=0.0)
    m2: Mapped[float] = mapped_column(Float, default=0.0)  # Welford's sum-of-squared-deltas

    updated_at: Mapped[datetime] = mapped_column(
        DateTime, server_default=func.now(), onupdate=func.now()
    )

    __table_args__ = (UniqueConstraint("user_id", "institution", name="uq_user_institution"),)
